#define R iResolution.xy
#define T iTime

#define rot(n) mat2(cos(n),-sin(n),sin(n),cos(n))

vec4 scene(vec3 p){
    float val = length(p);

    vec3 col = sin(vec3(.0,1.,3.)+val*.5)*.5+.5;

    vec2 q = sin(p.xy*rot(T*.2)+T);
    return vec4(col, step(.1,q.x+q.y));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = 2.*(fragCoord-R*.5)/R.y;

    vec3 bg = vec3(.03,.02,.1),
         col = bg;

    for(float i=9.; i>.5; i--){
        float d = length(vec2(length(uv),i));
        vec4 o = scene(vec3(2.*uv*d, d));
        o.rgb = mix(o.rgb, bg, 1.-exp(-i*.5));
        col = mix(col, o.rgb, o.a);
    }

    fragColor = vec4(pow(col,vec3(.454545)),1.0);
}
